function relInside(root, filePath) {
  const resolved = path.resolve(root, filePath);
  const abs = fs.existsSync(resolved) ? realpath(resolved) : path.join(realpath(path.dirname(resolved)), path.basename(resolved));
  const rel = path.relative(realpath(root), abs);
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) return null;
  return toPosix(rel);
}

function checkPackageJson(ctx, rel) {
  let pkg;
  try {
    pkg = JSON.parse(lib.readText(ctx.root, rel));
  } catch (err) {
    return [lib.finding('error', rel, `package.json is not valid JSON (${err.message})`, OWNER_NPM)];
  }

function checkFile(root, rel, ctx = makeContext(root)) {
  if (!lib.exists(root, rel)) return [];
  const base = path.posix.basename(rel);
  try {
    if (rel.endsWith('.csproj')) return checkProjectFile(ctx, rel);
    if (base === 'Directory.Packages.props') return checkPackagesProps(ctx, rel);
    if (base === 'package.json') return checkPackageJson(ctx, rel);
  } catch (err) {
    return [lib.finding('error', rel, `manifest could not be read (${err.message})`, base === 'package.json' ? OWNER_NPM : OWNER_NUGET)];
  }

for (let i = 1; i < words.length; i += 1) {
  const w = words[i];
  if (w === '--') break;
  if (w.startsWith('-')) {
    options.push(w);
    if (values.has(w)) i += 1;
    continue;
  }
  if (verb === null) {
    if (m.passThrough && Object.prototype.hasOwnProperty.call(m.passThrough, w)) {
      i += m.passThrough[w];
      continue;
    }
    verb = w.toLowerCase();
    continue;
  }
  positional.push(w);
}
let category = verb === null ? m.noVerb || null : m.verbs[verb] || null;
let specs = positional;
if (category === 'audit') {
  category = positional[0] === 'fix' ? 'update' : null;
  specs = [];
}
if (!category) return [];
const findings = [];
if (options.some(o => PEER_BYPASS.test(o))) findings.push({ kind: 'peer-bypass', segment });
if (category === 'remove') findings.push({ kind: 'dependency-removal', segment, specs });
else if (category === 'update' && !specs.length) findings.push({ kind: 'dependency-update', segment });
else if (category === 'install' || category === 'update') {
  const loose = specs.filter(s => !npmSpecIsExact(s));
  if (loose.length) findings.push({ kind: 'dependency-version', segment, specs: loose });
}
